//! Rust-side UI strings (27-mac-decisions M6): tray / menu-bar items and tooltip,
//! native window titles and the error text commands return to the page.
//!
//! One table holds every `(key, vi, en)` triple, so a string cannot exist in one
//! language only. The table is generated by `ui/scripts/strings.py`, the same
//! source that feeds the page's dictionaries. The active language is
//! `system.language` from the shared config.

use tauri::Manager;

#[path = "i18n_table.rs"]
mod table;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Lang {
    Vi,
    En,
}

impl From<vkb_config::Language> for Lang {
    fn from(value: vkb_config::Language) -> Self {
        match value {
            vkb_config::Language::Vi => Lang::Vi,
            vkb_config::Language::En => Lang::En,
        }
    }
}

/// The language the user has selected right now.
pub fn current() -> Lang {
    crate::commands::config_cell().read().system.language.into()
}

/// Look `key` up in `lang`. An unknown key returns the key itself, which is
/// visible in the UI and caught by the table test.
pub fn tr(lang: Lang, key: &str) -> &'static str {
    for (k, vi, en) in table::TABLE {
        if *k == key {
            return match lang {
                Lang::Vi => vi,
                Lang::En => en,
            };
        }
    }
    // Unknown key: empty, so callers can fall back to the key itself.
    ""
}

/// Replace `{name}` placeholders.
fn fill(text: &str, args: &[(&str, &str)]) -> String {
    let mut out = text.to_string();
    for (name, value) in args {
        out = out.replace(&format!("{{{name}}}"), value);
    }
    out
}

/// Translate with the current language.
pub fn t(key: &str) -> String {
    tf(key, &[])
}

/// Translate with the current language and fill `{name}` placeholders.
pub fn tf(key: &str, args: &[(&str, &str)]) -> String {
    tf_in(current(), key, args)
}

pub fn tf_in(lang: Lang, key: &str, args: &[(&str, &str)]) -> String {
    let text = tr(lang, key);
    if text.is_empty() {
        return key.to_string();
    }
    fill(text, args)
}

/// Native title of a window by label, in `lang`.
pub fn window_title(lang: Lang, label: &str) -> Option<&'static str> {
    let key = match label {
        "main" => "rwin.main",
        "hotkeys" => "rwin.hotkeys",
        "advanced" => "rwin.advanced",
        "macros" => "rwin.macros",
        "about" => "rwin.about",
        _ => return None,
    };
    Some(tr(lang, key))
}

/// Re-title every open window after a language change.
pub fn retitle_windows(app: &tauri::AppHandle) {
    let lang = current();
    for label in ["main", "hotkeys", "advanced", "macros", "about"] {
        if let (Some(window), Some(title)) = (app.get_webview_window(label), window_title(lang, label))
        {
            let _ = window.set_title(title);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_key_has_both_languages_and_is_unique() {
        let mut seen = std::collections::HashSet::new();
        for (key, vi, en) in table::TABLE {
            assert!(seen.insert(*key), "duplicate key {key}");
            assert!(!vi.trim().is_empty(), "empty vi for {key}");
            assert!(!en.trim().is_empty(), "empty en for {key}");
            let holders = |text: &str| {
                let mut found: Vec<String> = text
                    .split('{')
                    .skip(1)
                    .filter_map(|rest| rest.split('}').next())
                    .map(str::to_string)
                    .collect();
                found.sort();
                found
            };
            assert_eq!(holders(vi), holders(en), "placeholder mismatch for {key}");
        }
    }

    #[test]
    fn unknown_key_reads_as_the_key() {
        assert_eq!(tf_in(Lang::En, "no.such.key", &[]), "no.such.key");
    }

    #[test]
    fn placeholders_are_filled() {
        assert_eq!(
            tf_in(Lang::En, "tray.update", &[("version", "0.9.9")]),
            "Update v0.9.9 available"
        );
        assert_eq!(
            tf_in(Lang::Vi, "tray.update", &[("version", "0.9.9")]),
            "Có bản cập nhật v0.9.9"
        );
    }

    #[test]
    fn windows_have_titles() {
        for label in ["main", "hotkeys", "advanced", "macros", "about"] {
            assert!(window_title(Lang::En, label).is_some());
        }
        assert_eq!(window_title(Lang::Vi, "main"), Some("Cài đặt VietKB"));
    }
}
